"""Configuration: ~/.config/ai-delegate/config.yaml, with defaults for everything."""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from ai_delegate.bench import BenchConfig

CONFIG_PATH = Path(
    os.environ.get("AI_DELEGATE_CONFIG", "~/.config/ai-delegate/config.yaml")
).expanduser()
# Generated by `ai-delegate routes --write` from ai-bench results (M3).
ROUTES_PATH = CONFIG_PATH.with_name("routes.yaml")

# Ordered candidates per kind of work. M3 regenerates these from ai-bench results; until then
# they follow DESIGN.md: fast drafting on flint or nemotron-lightning, careful review on
# ThinkingCap. A name matches a model's id, name or alias, on any machine.
DEFAULT_ROUTES: dict[str, list[str]] = {
    "ask": ["flint", "deepseek-v4-flash", "nemotron-3.5-lightning-30b-a3b", "qwen3.8-27b"],
    "review": ["thinkingcap-qwen3.8-27b", "deepseek-v4-flash", "flint", "qwen3.8-27b"],
    # ai-factory's Builder binding: flint first.
    "delegate": ["flint", "deepseek-v4-flash", "qwen3.8-27b"],
    # Reading and reasoning over code: careful, then fast.
    "research": ["deepseek-v4-flash", "thinkingcap-qwen3.8-27b", "flint"],
}
DEFAULT_TIMEOUTS: dict[str, float] = {"ask": 300.0, "review": 600.0}


@dataclass
class Jobs:
    """Delegated jobs (M2): the sandbox and the per-job budgets (as ai-factory's watchdog)."""

    sandbox: str = "docker"  # or "local": pi runs on the host in the job's clone, unisolated
    image: str = "ai-factory/executor-base:latest"
    cpus: str = "4"
    memory: str = "8g"
    time_limit_s: float = 1800
    max_requests: int = 80
    max_tokens: int = 400_000  # new tokens: unseen prompt plus completions
    max_diff_lines: int = 800
    max_running: int = 2
    default_context: int = 131_072  # when ai-swap doesn't report a model's window


@dataclass
class Config:
    endpoint: str = "http://studio.local:8080"
    routes: dict[str, list[str]] = field(default_factory=lambda: dict(DEFAULT_ROUTES))
    timeouts: dict[str, float] = field(default_factory=lambda: dict(DEFAULT_TIMEOUTS))
    max_input_bytes: int = 400_000  # files and diffs sent with one call
    max_output_tokens: int = 32_768  # cap on a quarter of the model's context
    jobs: Jobs = field(default_factory=Jobs)
    bench: BenchConfig = field(default_factory=BenchConfig)
    # Where each tool's list came from: "defaults", "ai-bench (<date>)" or "config.yaml".
    route_source: dict[str, str] = field(default_factory=dict)
    scores: dict[str, dict[str, Any]] = field(default_factory=dict)
    source: str = "defaults"


def load(path: Path = CONFIG_PATH, routes_path: Path | None = None) -> Config:
    cfg = Config()
    cfg.route_source = {tool: "defaults" for tool in cfg.routes}
    routes_path = routes_path or path.with_name("routes.yaml")
    if routes_path.is_file():
        doc: dict[str, Any] = yaml.safe_load(routes_path.read_text()) or {}
        when = str(doc.get("generated", ""))[:10]
        for tool, names in (doc.get("routes") or {}).items():
            if names:
                cfg.routes[tool] = [str(n) for n in names]
                cfg.route_source[tool] = f"ai-bench ({when})"
        cfg.scores = doc.get("scores") or {}
    if path.is_file():
        raw: dict[str, Any] = yaml.safe_load(path.read_text()) or {}
        cfg.source = str(path)
        cfg.endpoint = str(raw.get("endpoint", cfg.endpoint))
        for tool in ("ask", "review", "delegate", "research"):
            section = raw.get(tool) or {}
            if "models" in section:
                cfg.routes[tool] = [str(m) for m in section["models"] or []]
                cfg.route_source[tool] = "config.yaml"
            if "timeout_s" in section:
                cfg.timeouts[tool] = float(section["timeout_s"])
        cfg.max_input_bytes = int(raw.get("max_input_bytes", cfg.max_input_bytes))
        cfg.max_output_tokens = int(raw.get("max_output_tokens", cfg.max_output_tokens))
        for key, value in (raw.get("jobs") or {}).items():
            if key not in Jobs.__dataclass_fields__:
                raise ValueError(f"{path}: unknown jobs setting {key!r}")
            current = getattr(cfg.jobs, key)
            setattr(cfg.jobs, key, type(current)(value))
        for key, value in (raw.get("bench") or {}).items():
            if key not in BenchConfig.__dataclass_fields__:
                raise ValueError(f"{path}: unknown bench setting {key!r}")
            setattr(cfg.bench, key, value)
    if env := os.environ.get("AI_DELEGATE_ENDPOINT"):
        cfg.endpoint = env
    cfg.endpoint = cfg.endpoint.rstrip("/")
    return cfg
